<?php
require_once __DIR__.'/../bootstrap/app.php';require_role('MEMBER');$u=current_user();$gym=db_all('SELECT * FROM GYM_ATTENDANCE WHERE MemberID=? ORDER BY CheckInAt DESC LIMIT 100','i',[$u['MemberID']]);$class=db_all("SELECT ca.Status,ca.MarkedAt,c.ClassName,s.StartsAt FROM CLASS_ATTENDANCE ca JOIN ENROLLMENT e ON e.EnrollmentID=ca.EnrollmentID JOIN CLASS_SESSION s ON s.SessionID=ca.SessionID JOIN CLASS c ON c.ClassID=s.ClassID WHERE e.MemberID=? ORDER BY s.StartsAt DESC LIMIT 100",'i',[$u['MemberID']]);$pageTitle='My attendance';$pageSubtitle='Gym visits and class participation';include ROOT_PATH.'/includes/header.php';?><div class="dash-grid"><div class="dash-card"><div class="dash-card-title">Gym visits</div><ul class="dash-list"><?php foreach($gym as $r):?><li><span class="name"><?=e(date('d M Y',strtotime($r['CheckInAt'])))?></span><span class="meta"><?=e(date('H:i',strtotime($r['CheckInAt'])))?>–<?=$r['CheckOutAt']?e(date('H:i',strtotime($r['CheckOutAt']))):'Open'?></span></li><?php endforeach;if(!$gym):?><li><span class="meta">No gym visits recorded.</span></li><?php endif;?></ul></div><div class="dash-card"><div class="dash-card-title">Class attendance</div><ul class="dash-list"><?php foreach($class as $r):?><li><span class="name"><?=e($r['ClassName'])?></span><span class="badge <?=$r['Status']==='PRESENT'?'badge-green':'badge-grey'?>"><?=e($r['Status'])?></span></li><?php endforeach;if(!$class):?><li><span class="meta">No class attendance recorded.</span></li><?php endif;?></ul></div></div><?php include ROOT_PATH.'/includes/footer.php';?>
